from contextlib import asynccontextmanager
import logging
import os
from pathlib import Path
from fastapi import FastAPI, Request, status
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import JSONResponse
from fastapi.staticfiles import StaticFiles

from app.config import (
    CORS_ORIGINS,
    DATASET_DIR,
    DISCLAIMER_TEXT,
    EVALUATION_DIR,
    MODEL_FILE_PATH,
)
from app.routes import auth, dataset, evaluation, health, model, predict, student, tasks

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
)
logger = logging.getLogger("axonova")

@asynccontextmanager
async def lifespan(app: FastAPI):
    logger.info("Initializing AXONOVA Platform...")
    if MODEL_FILE_PATH.exists():
        logger.info("CNN Model checkpoint detected at %s", MODEL_FILE_PATH)
    else:
        logger.warning(
            "No trained model found at %s. Please train the model using 'python -m model.train'.",
            MODEL_FILE_PATH,
        )
    yield

app = FastAPI(
    title="AXONOVA API",
    description="Deep Learning-Based Brain MRI Image Classification & Educational Analysis API",
    version="1.0.0",
    docs_url="/docs",
    redoc_url="/redoc",
    lifespan=lifespan,
)

# CORS configuration
app.add_middleware(
    CORSMiddleware,
    allow_origins=CORS_ORIGINS,
    allow_credentials=True,
    allow_methods=["GET", "POST", "OPTIONS"],
    allow_headers=["*"],
)

# Include Routers
app.include_router(health.router)
app.include_router(auth.router)
app.include_router(tasks.router)
app.include_router(model.router)
app.include_router(predict.router)
app.include_router(evaluation.router)
app.include_router(dataset.router)
app.include_router(student.router)

# Mount static evaluation results and dataset if available
if EVALUATION_DIR.exists():
    app.mount("/static/evaluation", StaticFiles(directory=str(EVALUATION_DIR)), name="evaluation_static")
if DATASET_DIR.exists():
    app.mount("/static/dataset", StaticFiles(directory=str(DATASET_DIR)), name="dataset_static")

@app.exception_handler(Exception)
async def global_exception_handler(request: Request, exc: Exception):
    logger.error("Unhandled exception processing %s: %s", request.url.path, str(exc), exc_info=True)
    return JSONResponse(
        status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
        content={
            "detail": "An internal server error occurred while processing the request.",
            "error_type": type(exc).__name__,
            "disclaimer": DISCLAIMER_TEXT,
        },
    )

@app.get("/")
async def root():
    return {
        "platform": "AXONOVA",
        "description": "Deep Learning-Based Brain MRI Image Classification Platform",
        "documentation": "/docs",
        "health_check": "/api/health",
        "disclaimer": DISCLAIMER_TEXT,
    }
